// PendingReleaseFile is the installer hand-off name under the staging directory.
const PendingReleaseFile = "pending-release.json"

// SourceInstaller identifies installer-staged claims and wire results (D-089).
const SourceInstaller = "installer"

// PendingRelease is the record packaging/installer writes. The writer emits
// release_id, manifest_sha256, artifact_path, tree_path, updater_command,
// manifest_path and a fresh request_id. The retained envelope is Verified.Raw,
// mode 0600 under update-staging. Inline manifest remains supported. Unknown
// fields, including request_id, participate in the local integrity digest.
// tree_path is not installed. updater_command is not executed.
type PendingRelease struct {
	ReleaseID      string          `json:"release_id,omitempty"`
	ManifestSHA256 string          `json:"manifest_sha256,omitempty"`
	ArtifactPath   string          `json:"artifact_path,omitempty"`
	TreePath       string          `json:"tree_path,omitempty"`
	UpdaterCommand string          `json:"updater_command,omitempty"`
	ManifestPath   string          `json:"manifest_path,omitempty"`
	Manifest       json.RawMessage `json:"manifest,omitempty"`
	digest         string
}

// ApplyPending verifies a staged release and runs it through the update
// state machine. path is required. A missing file is an error. The oneshot
// uses applyPendingLocked with required false.
func (e *Engine) ApplyPending(ctx context.Context, path string) error {
	if strings.TrimSpace(path) == "" {
		return errors.New("updater: pending path is required")
	}
	var err error
	path, err = filepath.Abs(path)
	if err != nil {
		return err
	}
	return e.withLockFor(ctx, "apply", func() error {
		if err := e.open(ctx); err != nil {
			return err
		}
		// Recovery may seal this very pending job and consume its record.
		rec, readErr := readPending(path)
		_, before := os.Lstat(path)
		recovered := e.recoverLocked(ctx)
		if recovered != nil && !errors.Is(recovered, ErrMembersBlocked) {
			return recovered
		}
		applyErr := e.applyPendingLocked(ctx, path, before != nil)
		// Recovery can finish and consume this record before apply sees it.
		// Report that exact job's sealed failure, never an unrelated snapshot.
		releaseID, parseErr := uuid.Parse(rec.ReleaseID)
		if readErr == nil && parseErr == nil {
			job, err := e.Journal.InstallerJob(ctx, releaseID.String(), rec.ManifestSHA256, e.Node.Incarnation.String())
			if err != nil && !errors.Is(err, updatejournal.ErrNotFound) {
				return err
			}
			if job.Phase == updatejournal.JobDone && job.Outcome == string(api.UpdateResultStateFailed) {
				c, err := decodeClaimed(job.IntentJSON)
				if err != nil {
					return err
				}
				if c.PendingSHA256 == rec.digest && c.PendingPath == path {
					if errors.Is(recovered, ErrMembersBlocked) {
						txn, err := e.Journal.LastTxn(ctx)
						// A sealed pre-stop final-sample failure is an apply
						// failure (1), including replay of pre-D-125 journals.
						// Recover still reports the blocked gate (2). Destructive
						// failures and unrelated recovery keep their exit 2.
						if err != nil || txn.JobID != job.JobID || txn.Attempt != job.Attempt ||
							txn.Stage != updatejournal.StageRolledBack || txn.Destructive ||
							txn.ErrorStage != string(api.UpdateStageFinalSample) {
							return fmt.Errorf("updater: installer outcome=%s (%s): %w", job.Outcome, job.ErrorCode, ErrMembersBlocked)
						}
					}
					return permanent(apierr.Code(job.ErrorCode), fmt.Sprintf("installer outcome=%s", job.Outcome))
				}
			}
		}
		if applyErr != nil {
			return applyErr
		}
		if errors.Is(recovered, ErrMembersBlocked) {
			blocked, _ := e.Journal.BlocksForwarding(ctx)
			if blocked {
				return ErrMembersBlocked
			}
		}
		return nil
	})
}

func (e *Engine) pendingRecordPath() string {
	if e == nil || e.Layout.Staging == "" {
		return ""
	}
	return filepath.Join(e.Layout.Staging, PendingReleaseFile)
}

// applyPendingLocked applies path when it exists. required is false for the
// oneshot, where a missing file is no work.
func (e *Engine) applyPendingLocked(ctx context.Context, path string, required bool) error {
	if path == "" {
		return nil
	}
	var err error
	path, err = filepath.Abs(path)
	if err != nil {
		return err
	}
	if _, err := os.Lstat(path); err != nil {
		if errors.Is(err, os.ErrNotExist) && !required {
			return nil
		}
		return err
	}
	_, err = e.applyPendingBody(ctx, path)
	return err
}

func (e *Engine) applyPendingBody(ctx context.Context, path string) (string, error) {
	rec, err := readPending(path)
	if err != nil {
		return "", err
	}
	releaseID, err := uuid.Parse(rec.ReleaseID)
	if err != nil || releaseID == uuid.Nil || !validSHA256(rec.ManifestSHA256) {
		return "", permanent(apierr.ValidationFailed, "pending release record")
	}
	if e.Node.BootID == uuid.Nil {
		return "", errors.New("updater: boot_id is required when the kernel boot id is unreadable")
	}
	c, err := e.installerClaim(ctx, path, releaseID, rec.ManifestSHA256)
	if err != nil {
		return "", err
	}
	c.PendingSHA256 = rec.digest
	jobID := c.Intent.JobId.String()
	// Reuse the original claim rather than a new generation or boot result.
	// A retry must use the same intent and result bytes after a restart.
	stored, err := e.Journal.InstallerJob(ctx, releaseID.String(), rec.ManifestSHA256, e.Node.Incarnation.String())
	if err == nil {
		// Keep legacy local claims and accepted history under their original ID.
		jobID = stored.JobID
		c, err = decodeClaimed(stored.IntentJSON)
		if err != nil {
			return jobID, err
		}
		if c.PendingSHA256 != rec.digest || c.PendingPath != path {
			return jobID, permanent(apierr.ValidationFailed, "pending record changed for an existing installer job")
		}
		if stored.Phase == updatejournal.JobDone {
			return jobID, e.consumeInstallerPending(c, stored.Outcome)
		}
	} else if errors.Is(err, updatejournal.ErrNotFound) {
		raw, err := json.Marshal(c)
		if err != nil {
			return jobID, err
		}
		stored, err = e.Journal.RecordJob(ctx, updatejournal.Job{
			JobID: jobID, Attempt: c.Intent.Attempt, Generation: c.Intent.Generation,
			ReleaseID: releaseID.String(), ManifestSHA256: strings.ToLower(rec.ManifestSHA256), IntentJSON: raw,
		})
		if err != nil {
			return jobID, err
		}
	} else {
		return jobID, err
	}
	fail := func(cause error) (string, error) {
		if retryable(cause) {
			return jobID, cause
		}
		code := apierr.ValidationFailed
		if op := asOp(cause); op != nil {
			code = op.Code
		}
		if err := e.failJob(ctx, stored, c, code, api.UpdateStageVerify); err != nil {
			return jobID, err
		}
		return jobID, cause
	}
	if e.Node.Revoked || e.drifted(c) {
		if err := e.noteBlocked(ctx, c, updatejournal.OutcomeFailed); err != nil {
			return jobID, err
		}
		return fail(permanent(apierr.IdentityRevoked, "installer node identity"))
	}
	if containsID(e.RevokedReleaseIDs, releaseID) || containsID(c.Revoked, releaseID) {
		return fail(permanent(apierr.ReleaseNotApproved, "revoked release"))
	}
	env, err := pendingEnvelope(rec)
	if err != nil {
		return fail(err)
	}
	manifest, art, err := e.verifyStaged(ctx, rec, env)
	if err != nil {
		return fail(err)
	}
	artifact, err := e.snapshotStagedArtifact(rec.ArtifactPath, art)
	if err != nil {
		return fail(err)
	}
	defer os.Remove(artifact)
	if err := release.CheckArtifact(manifest, e.Platform.Architecture, artifact); err != nil {
		return fail(artifactOp(err))
	}
	// An installer-created current pointer without updater metadata must not
	// be mistaken for an empty node (which would skip schema/rollback checks).
	pointers, err := e.Journal.Pointers(ctx)
	if err != nil {
		return jobID, err
	}
	current, err := e.Layout.currentID()
	if err != nil {
		return jobID, err
	}
	if current != pointers.CurrentRelease {
		return fail(permanent(apierr.CheckpointFailed, "current release has no matching updater journal"))
	}
	e.log().Info("applying installer pending release", "release_id", releaseID.String())
	if done, err := e.maybeAlreadyCurrent(ctx, c, stored); done || err != nil {
		return jobID, err
	}
	same, err := fsutil.SameFilesystem(e.Layout.Releases, filepath.Dir(e.Layout.Current))
	if err != nil || !same {
		return jobID, e.failInstaller(ctx, stored, c, permanent(apierr.StartFailed, "releases and current are not on the same filesystem"))
	}
	if err := e.installTree(ctx, c, manifest, env, art, artifact); err != nil {
		if retryable(err) {
			return jobID, err
		}
		return jobID, e.failInstaller(ctx, stored, c, err)
	}
	if err := e.setPhase(ctx, stored, updatejournal.JobApplying); err != nil {
		return jobID, err
	}
	txn, err := e.beginOrResume(ctx, c, manifest)
	if err != nil {
		return jobID, err
	}
	if err := e.continueTxn(ctx, txn); err != nil {
		return jobID, err
	}
	return jobID, nil
}

func (e *Engine) installerClaim(ctx context.Context, path string, releaseID uuid.UUID, manifestSHA string) (claimed, error) {
	gen, err := e.installerGeneration(ctx)
	if err != nil {
		return claimed{}, err
	}
	policy, err := e.installerPolicy(ctx)
	if err != nil {
		return claimed{}, err
	}
	g, err := e.Journal.GateRecord(ctx)
	if err != nil {
		return claimed{}, err
	}
	intent := publicationOrDisabled(g.PublicationIntent)
	revoked, err := e.signedRevokedIDs(ctx)
	if err != nil {
		return claimed{}, err
	}
	ptr, err := e.Journal.Pointers(ctx)
	if err != nil {
		return claimed{}, err
	}
	var rollback []uuid.UUID
	for _, raw := range []string{ptr.LastGood, ptr.CurrentRelease} {
		if id, err := uuid.Parse(raw); err == nil {
			rollback = unionUUIDs(rollback, []uuid.UUID{id})
		}
	}
	now := e.now()
	return claimed{
		Work: Work{
			Intent: api.UpdateIntent{
				Attempt:    1,
				Generation: gen, IncarnationId: e.Node.Incarnation,
				IssuedAt: now, JobId: installerjob.ID(releaseID, manifestSHA, e.Node.Incarnation),
				ManifestSha256: strings.ToLower(manifestSHA),
				NodeId:         e.Node.ID, PublicationIntent: intent, ReleaseId: releaseID,
				BatchId:  presence.NewNullNullable[uuid.UUID](),
				TargetId: presence.NewNullNullable[uuid.UUID](),
			},
			// A local request is not a serving authorization. The agent must
			// receive a valid desired state before member forwarding resumes.
			Revoked:          unionUUIDs(revoked, e.RevokedReleaseIDs),
			Serving:          rollback, // permits verified rollback; enforce keeps installer forwarding off
			PolicyGeneration: policy,
			PolicyKnown:      true,
		},
		BootID: e.Node.BootID, StateSchema: e.Platform.StateSchema,
		Source: SourceInstaller, PendingPath: path,
	}, nil
}

func (e *Engine) installerGeneration(ctx context.Context) (decstr.U64, error) {
	gen, _, ok, err := e.Journal.AcceptedGeneration(ctx)
	if err != nil {
		return 0, err
	}
	if !ok || gen == 0 {
		return decstr.MustParse("1"), nil
	}
	return gen, nil
}

func (e *Engine) installerPolicy(ctx context.Context) (decstr.U64, error) {
	gen, ok, err := e.Journal.AppliedConfig(ctx)
	if err != nil || !ok {
		return 0, err
	}
	return gen, nil
}

func publicationOrDisabled(s string) api.PublicationIntent {
	switch api.PublicationIntent(s) {
	case api.PublicationIntentPublished, api.PublicationIntentUnpublished, api.PublicationIntentDisabled:
		return api.PublicationIntent(s)
	default:
		return api.PublicationIntentDisabled
	}
}

func (e *Engine) verifyStaged(ctx context.Context, rec PendingRelease, env []byte) (api.ReleaseManifest, api.ManifestArtifact, error) {
	if e.ReleaseTrust == nil {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, permanent(apierr.KeyUntrusted, "release trust")
	}
	manifest, err := VerifyManifest(env, rec.ManifestSHA256, e.ReleaseTrust, e.now())
	if err != nil {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, err
	}
	if _, _, err := release.Verify(env, e.ReleaseTrust, e.now()); err != nil {
		if errors.Is(err, envelope.ErrKeyUntrusted) {
			return api.ReleaseManifest{}, api.ManifestArtifact{}, permanent(apierr.KeyUntrusted, "release signature")
		}
		return api.ReleaseManifest{}, api.ManifestArtifact{}, permanent(apierr.SignatureInvalid, "release signature")
	}
	id, parseErr := uuid.Parse(rec.ReleaseID)
	if parseErr != nil || manifest.ReleaseId != id {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, permanent(apierr.SignatureInvalid, "release_id")
	}
	schema, _ := e.Journal.StateSchema(ctx)
	if schema == 0 {
		schema = e.Platform.StateSchema
	}
	p, _ := e.Journal.Pointers(ctx)
	if err := checkCompat(manifest, e.Platform, schema, p.CurrentRelease != ""); err != nil {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, err
	}
	art, err := selectArtifact(manifest, e.Platform.OSID, e.Platform.OSVersion, e.Platform.Architecture)
	if err != nil {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, err
	}
	need, ok := sumU64(art.SizeBytes.Uint64(), art.InstalledSizeBytes.Uint64(), manifest.Rollback.RequiredFreeBytes.Uint64())
	if !ok {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, transient(apierr.DiskSpaceLow, "size overflow")
	}
	if err := e.ensureSpace(e.Layout.Releases, need); err != nil {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, err
	}
	if err := e.ensureSpace(e.Layout.Staging, art.SizeBytes.Uint64()); err != nil {
		return api.ReleaseManifest{}, api.ManifestArtifact{}, err
	}
	return manifest, art, nil
}

func (e *Engine) failInstaller(ctx context.Context, job updatejournal.Job, c claimed, cause error) error {
	code := apierr.ValidationFailed
	if op := asOp(cause); op != nil {
		code = op.Code
	}
	if err := e.failJob(ctx, job, c, code, api.UpdateStageVerify); err != nil {
		return err
	}
	return cause
}

// readLocalFile opens without following the final symlink and bounds the read.
// O_NONBLOCK prevents a substituted FIFO from hanging the updater.
func openLocalFile(path string) (*os.File, error) {
	f, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	st, err := f.Stat()
	if err != nil || !st.Mode().IsRegular() {
		_ = f.Close()
		return nil, permanent(apierr.ValidationFailed, "local input is not a regular file")
	}
	return f, nil
}

func readLocalFile(path string) ([]byte, error) {
	f, err := openLocalFile(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	raw, err := io.ReadAll(io.LimitReader(f, canonjson.MaxBytes+1))
	if err != nil {
		return nil, err
	}
	if len(raw) > canonjson.MaxBytes {
		return nil, permanent(apierr.ValidationFailed, "local JSON input is too large")
	}
	return raw, nil
}

func readPending(path string) (PendingRelease, error) {
	raw, err := readLocalFile(path)
	if err != nil {
		return PendingRelease{}, err
	}
	canonical, err := canonjson.Canonicalize(raw)
	if err != nil {
		return PendingRelease{}, permanent(apierr.ValidationFailed, "pending release record")
	}
	var rec PendingRelease
	if err := json.Unmarshal(canonical, &rec); err != nil {
		return rec, permanent(apierr.ValidationFailed, "pending release record")
	}
	sum := sha256.Sum256(canonical)
	rec.digest = hex.EncodeToString(sum[:])
	return rec, nil
}

func pendingEnvelope(rec PendingRelease) ([]byte, error) {
	raw := bytes.TrimSpace(rec.Manifest)
	if len(raw) > 0 && string(raw) != "null" {
		return append([]byte(nil), raw...), nil
	}
	if rec.ManifestPath == "" {
		return nil, permanent(apierr.SignatureInvalid, "pending record has no signed manifest")
	}
	raw, err := readLocalFile(rec.ManifestPath)
	if err != nil {
		return nil, permanent(apierr.SignatureInvalid, "pending manifest is unreadable")
	}
	return raw, nil
}

// Copy to a private updater file before verification. Extraction reads only
// this verified snapshot, never a staging pathname that could be replaced.
func (e *Engine) snapshotStagedArtifact(path string, art api.ManifestArtifact) (string, error) {
	src, err := openLocalFile(path)
	if err != nil {
		return "", permanent(apierr.ArtifactInvalid, "staged artifact is unreadable")
	}
	defer src.Close()
	dst, err := os.CreateTemp(e.Layout.Staging, ".installer-*.tar.zst")
	if err != nil {
		return "", transient(apierr.StoreUnavailable, "staged artifact snapshot")
	}
	ok := false
	defer func() {
		_ = dst.Close()
		if !ok {
			_ = os.Remove(dst.Name())
		}
	}()
	size := art.SizeBytes.Uint64()
	if size >= 1<<63-1 {
		return "", permanent(apierr.SizeMismatch, "staged artifact")
	}
	n, err := io.Copy(dst, io.LimitReader(src, int64(size)+1))
	if err != nil {
		return "", transient(apierr.StoreUnavailable, "staged artifact snapshot")
	}
	if n != int64(size) {
		return "", permanent(apierr.SizeMismatch, "staged artifact")
	}
	if err := dst.Close(); err != nil {
		return "", err
	}
	ok = true
	return dst.Name(), nil
}

// Snapshots are needed only during verification/extraction under the lock.
// An active transaction resumes from its installed, journaled release tree.
func (e *Engine) cleanInstallerSnapshots() error {
	entries, err := os.ReadDir(e.Layout.Staging)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasPrefix(entry.Name(), ".installer-") && strings.HasSuffix(entry.Name(), ".tar.zst") {
			if err := os.Remove(filepath.Join(e.Layout.Staging, entry.Name())); err != nil {
				return err
			}
		}
	}
	return nil
}

func artifactOp(err error) error {
	if err == nil {
		return nil
	}
	msg := err.Error()
	switch {
	case strings.Contains(msg, "HASH_MISMATCH"):
		return permanent(apierr.HashMismatch, "staged artifact")
	case strings.Contains(msg, "SIZE_MISMATCH"):
		return permanent(apierr.SizeMismatch, "staged artifact")
	case strings.Contains(msg, "UNSUPPORTED_PLATFORM"):
		return permanent(apierr.UnsupportedPlatform, "staged artifact")
	case strings.Contains(msg, "VALIDATION_FAILED"):
		return permanent(apierr.ValidationFailed, "staged artifact")
	default:
		return permanent(apierr.ArtifactInvalid, "staged artifact")
	}
}

func validSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		if !strings.ContainsRune("0123456789abcdefABCDEF", c) {
			return false
		}
	}
	return true
}

// finishInstaller records cleanup in the same durable transaction that seals
// the job, then renames the matching record and clears the cleanup obligation.
func (e *Engine) finishInstaller(ctx context.Context, c claimed, job updatejournal.Job, outcome, code string) error {
	if c.Source != SourceInstaller {
		return e.finish(ctx, job, outcome, code)
	}
	if err := e.Journal.FinishInstallerJob(ctx, job.JobID, job.Attempt, outcome, code); err != nil {
		return err
	}
	return e.consumeFinishedInstallerJobs(ctx)
}

func retryable(err error) bool {
	op := asOp(err)
	// Unclassified I/O failures and interruption leave the job available.
	return op == nil || op.Retry
}

func (e *Engine) consumeFinishedInstallerJobs(ctx context.Context) error {
	jobs, err := e.Journal.InstallerCleanups(ctx)
	if err != nil {
		return err
	}
	for _, job := range jobs {
		c, err := decodeClaimed(job.IntentJSON)
		if err != nil {
			return err
		}
		if c.Source != SourceInstaller {
			return permanent(apierr.ValidationFailed, "installer cleanup claim")
		}
		if err := e.consumeInstallerPending(c, job.Outcome); err != nil {
			return err
		}
		if err := e.Journal.ClearInstallerCleanup(ctx, job.JobID, job.Attempt); err != nil {
			return err
		}
	}
	return nil
}

func (e *Engine) consumeInstallerPending(c claimed, state string) error {
	if c.PendingPath == "" || c.PendingSHA256 == "" {
		return permanent(apierr.ValidationFailed, "installer cleanup identity")
	}
	rec, err := readPending(c.PendingPath)
	if errors.Is(err, os.ErrNotExist) {
		return fsutil.SyncDir(filepath.Dir(c.PendingPath))
	}
	if err != nil {
		return err
	}
	// A later installer may have staged a different record after a crash.
	// Completing the old job must never consume that new request.
	if rec.digest != c.PendingSHA256 {
		return nil
	}
	if !api.UpdateResultState(state).Valid() {
		return permanent(apierr.ValidationFailed, "installer result state")
	}
	dest := strings.TrimSuffix(c.PendingPath, ".json") + "." + state + ".json"
	if err := os.Rename(c.PendingPath, dest); err != nil {
		return err
	}
	return fsutil.SyncDir(filepath.Dir(c.PendingPath))
}

package updater

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"

	"github.com/TED-H-com/Freedom-VPN/node/internal/updatejournal"
	"github.com/TED-H-com/Freedom-VPN/node/updater/fsutil"
	"github.com/TED-H-com/Freedom-VPN/packaging/release"
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/TED-H-com/Freedom-VPN/pkg/apierr"
	"github.com/google/uuid"
)

// Seed verifies the installer's current release without switching, recovering,
// restarting services or claiming health. Only verified evidence is committed.
func (e *Engine) Seed(ctx context.Context, manifestPath, tree string) error {
	if strings.TrimSpace(manifestPath) == "" || strings.TrimSpace(tree) == "" {
		return permanent(apierr.ValidationFailed, "seed requires manifest and tree")
	}
	return e.withLockFor(ctx, "seed", func() error {
		if err := e.open(ctx); err != nil {
			return err
		}
		return e.seedLocked(ctx, manifestPath, tree)
	})
}

func (e *Engine) seedLocked(ctx context.Context, manifestPath, tree string) error {
	if e.Node.Revoked || e.Node.BootID == uuid.Nil {
		return permanent(apierr.IdentityRevoked, "seed requires a valid node and boot identity")
	}
	raw, err := readLocalFile(manifestPath)
	if err != nil {
		return err
	}
	if e.ReleaseTrust == nil {
		return permanent(apierr.KeyUntrusted, "release trust")
	}
	signed, _, err := release.Verify(raw, e.ReleaseTrust, e.now())
	if err != nil {
		return permanent(apierr.SignatureInvalid, "seed release signature or schema")
	}
	m, err := release.ParsedManifest(signed)
	if err != nil {
		return err
	}
	revoked, err := e.signedRevokedIDs(ctx)
	if err != nil {
		return err
	}
	if containsID(revoked, m.ReleaseId) || containsID(e.RevokedReleaseIDs, m.ReleaseId) {
		return permanent(apierr.ReleaseNotApproved, "seed release is revoked")
	}
	if err := checkCompat(m, e.Platform, 0, false); err != nil {
		return err
	}
	if e.Platform.StateSchema != m.Compatibility.StateSchemaTo {
		return permanent(apierr.SchemaIncompatible, "seed state schema differs")
	}
	if err := e.seedTreePath(tree, m.ReleaseId.String()); err != nil {
		return err
	}
	pointers, err := e.Journal.Pointers(ctx)
	if err != nil {
		return err
	}
	if pointers.CurrentRelease != "" && pointers.CurrentRelease != m.ReleaseId.String() {
		return permanent(apierr.CheckpointFailed, "seed refused: current release differs from journal")
	}
	manifestSHA, err := release.EnvelopeSHA256(raw)
	if err != nil {
		return err
	}
	art, err := selectArtifact(m, e.Platform.OSID, e.Platform.OSVersion, e.Platform.Architecture)
	if err != nil {
		return err
	}
	treeHash, err := e.verifySeedTree(ctx, tree, m, art)
	if err != nil {
		return err
	}
	// Recheck the live pointer before the atomic commit; shared writers hold
	// the node lock for the whole verification interval.
	if err := e.seedTreePath(tree, m.ReleaseId.String()); err != nil {
		return err
	}
	if err := e.Journal.SeedBaseline(ctx, updatejournal.Release{
		ReleaseID: m.ReleaseId.String(), ManifestSHA256: manifestSHA, ManifestEnvelope: raw,
		ArtifactSHA256: art.Sha256, TreeHash: treeHash, StateSchemaTo: m.Compatibility.StateSchemaTo,
	}, e.Node.BootID.String()); err != nil {
		return permanent(apierr.CheckpointFailed, err.Error())
	}
	e.log().Info("verified installer baseline seeded", "release_id", m.ReleaseId.String())
	return nil
}

func (e *Engine) seedTreePath(tree, id string) error {
	abs, err := filepath.Abs(tree)
	if err != nil {
		return err
	}
	expected, err := filepath.Abs(e.Layout.releaseDir(id))
	if err != nil {
		return err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil || resolved != abs || abs != expected {
		return permanent(apierr.CheckpointFailed, "seed tree must be the resolved release directory")
	}
	st, err := os.Lstat(abs)
	if err != nil || !st.IsDir() {
		return permanent(apierr.CheckpointFailed, "seed tree is not a directory")
	}
	st, err = os.Lstat(e.Layout.Current)
	if err != nil || st.Mode()&os.ModeSymlink == 0 {
		return permanent(apierr.CheckpointFailed, "seed requires the current symlink")
	}
	current, err := filepath.EvalSymlinks(e.Layout.Current)
	if err != nil {
		return err
	}
	current, err = filepath.Abs(current)
	if err != nil || current != abs {
		return permanent(apierr.CheckpointFailed, "seed tree differs from current")
	}
	return nil
}

// The manifest authenticates the archive, not a per-file inventory. Use the
// apply path's artifact verifier, safe extractor and full tree hash to derive
// that inventory. Never promote a hash computed solely from an untrusted tree.
func (e *Engine) verifySeedTree(ctx context.Context, tree string, m api.ReleaseManifest, art api.ManifestArtifact) (string, error) {
	if art.SizeBytes.Uint64() >= 1<<63-1 || art.InstalledSizeBytes.Uint64() >= 1<<63-1 {
		return "", permanent(apierr.SizeMismatch, "seed artifact size")
	}
	need, ok := sumU64(art.SizeBytes.Uint64(), art.InstalledSizeBytes.Uint64())
	if !ok {
		return "", transient(apierr.DiskSpaceLow, "seed size overflow")
	}
	if err := e.ensureSpace(e.Layout.Staging, need); err != nil {
		return "", err
	}
	scratch, err := os.MkdirTemp(e.Layout.Staging, ".seed-*")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(scratch)
	archive := filepath.Join(scratch, "artifact.tar.zst")
	cached := filepath.Join(e.Layout.Staging, art.Sha256+".tar.zst")
	if _, err := os.Lstat(cached); err == nil {
		archive, err = e.snapshotStagedArtifact(cached, art)
		if err != nil {
			return "", err
		}
		defer os.Remove(archive)
	} else if !errors.Is(err, os.ErrNotExist) {
		return "", err
	} else if err := e.download(ctx, art.Url, archive, art.Sha256, hashRaw, int64(art.SizeBytes), int64(art.SizeBytes), nil); err != nil {
		return "", err
	}
	if err := release.CheckArtifact(m, e.Platform.Architecture, archive); err != nil {
		return "", artifactOp(err)
	}
	f, err := os.Open(archive)
	if err != nil {
		return "", err
	}
	defer f.Close()
	reference := filepath.Join(scratch, "tree")
	if err := ExtractArchive(f, reference, ExtractOptions{MaxBytes: int64(art.InstalledSizeBytes), Deny: e.Layout.PersistentDirs()}); err != nil {
		return "", err
	}
	want, err := fsutil.TreeHash(reference)
	if err != nil {
		return "", err
	}
	got, err := fsutil.TreeHash(tree)
	if err != nil {
		return "", permanent(apierr.HashMismatch, "seed tree contains an unreadable or unsupported entry")
	}
	if got != want {
		return "", permanent(apierr.HashMismatch, "seed tree differs from the signed artifact")
	}
	return got, nil
}

package updater

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/internal/updatejournal"
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/TED-H-com/Freedom-VPN/pkg/api/presence"
	"github.com/TED-H-com/Freedom-VPN/pkg/apierr"
	"github.com/TED-H-com/Freedom-VPN/pkg/canonjson"
	"github.com/TED-H-com/Freedom-VPN/pkg/decstr"
	"github.com/google/uuid"
)

// Version is the updater binary version reported in the user agent.
// Security decisions use release_id and minimum_updater_version, not this
// string (§13.3).
const Version = "1.0.0"

// resultID is stable across a replay of the same job, attempt and state.
// UUIDv7 is not replay-stable, so this is UUIDv5 over those fields.
func resultID(jobID string, attempt int, state api.UpdateResultState) uuid.UUID {
	name := fmt.Sprintf("fvpn-update-result|%s|%d|%s", jobID, attempt, state)
	return uuid.NewSHA1(uuid.NameSpaceOID, []byte(name))
}

type resultInput struct {
	Claimed         claimed
	State           api.UpdateResultState
	Stage           api.UpdateStage
	Code            apierr.Code
	Current         string
	Previous        string
	Recovery        bool
	Forwarding      bool
	Started         time.Time
	Finished        time.Time
	Schema          int
	Health          *api.UpdateHealth
	CandidateHealth *api.UpdateHealth
	Checkpoint      *api.UpdateUsageCheckpoint
}

func buildResult(in resultInput) (payload []byte, hash string, id uuid.UUID, err error) {
	c := in.Claimed
	schema := in.Schema
	if schema < 1 {
		schema = 1
	}
	started := utcSec(in.Started)
	if started.IsZero() {
		started = utcSec(c.Intent.IssuedAt)
	}
	finished := utcSec(in.Finished)
	if finished.IsZero() {
		finished = started
	}
	res := api.UpdateResult{
		Attempt:                 c.Intent.Attempt,
		BatchId:                 c.Intent.BatchId,
		BootId:                  c.BootID,
		CurrentReleaseId:        presence.FromPointer(parseID(in.Current)),
		ErrorCode:               presence.FromPointer(codePtr(in.Code)),
		FinishedAt:              presence.FromPointer(timePtr(finished)),
		Generation:              c.Intent.Generation,
		Health:                  presence.FromPointer(in.Health),
		IncarnationId:           c.Intent.IncarnationId,
		JobId:                   c.Intent.JobId,
		ManifestSha256:          c.Intent.ManifestSha256,
		MemberForwardingEnabled: in.Forwarding,
		NodeId:                  c.Intent.NodeId,
		PolicyGeneration:        c.PolicyGeneration,
		PreviousReleaseId:       presence.FromPointer(parseID(in.Previous)),
		PublicationIntent:       c.Intent.PublicationIntent,
		RecoveryRequired:        presence.NewRequired(in.Recovery),
		RequestedReleaseId:      c.Intent.ReleaseId,
		ResultId:                resultID(c.Intent.JobId.String(), c.Intent.Attempt, in.State),
		Stage:                   presence.FromPointer(stagePtr(in.Stage)),
		StartedAt:               started,
		State:                   in.State,
		StateSchemaVersion:      schema,
		TargetId:                c.Intent.TargetId,
		UsageCheckpoint:         presence.FromPointer(in.Checkpoint),
	}
	if c.Source == SourceInstaller {
		source := api.UpdateResultSourceInstaller
		res.Source = &source
	}
	if in.State == api.UpdateResultStateRolledBack {
		res.CandidateHealth = presence.FromPointer(in.CandidateHealth)
	}
	raw, err := json.Marshal(res)
	if err != nil {
		return nil, "", uuid.Nil, err
	}
	hash, err = canonjson.HashHex(raw, "payload_hash")
	if err != nil {
		return nil, "", uuid.Nil, err
	}
	res.PayloadHash = hash
	raw, err = json.Marshal(res)
	if err != nil {
		return nil, "", uuid.Nil, err
	}
	canon, err := canonjson.Canonicalize(raw)
	if err != nil {
		return nil, "", uuid.Nil, err
	}
	return canon, hash, res.ResultId, nil
}

func (e *Engine) enqueueResult(ctx context.Context, in resultInput) error {
	if e.Journal == nil {
		return errors.New("updater: policy generation is not applied")
	}
	gen, err := e.policyForResult(ctx, in.Claimed)
	if err != nil {
		return err
	}
	// The reported generation is the applied desired-state config_generation.
	// It is not the job generation and not a desired state that was only
	// downloaded (D-043).
	in.Claimed.PolicyGeneration = gen
	in.Code = postedResultCode(in.Code)
	payload, hash, id, err := buildResult(in)
	if err != nil {
		return err
	}
	entry := updatejournal.OutboxEntry{
		ResultID:    id.String(),
		JobID:       in.Claimed.Intent.JobId.String(),
		Attempt:     in.Claimed.Intent.Attempt,
		Generation:  in.Claimed.Intent.Generation,
		State:       string(in.State),
		Payload:     payload,
		PayloadHash: hash,
	}
	if err := e.Journal.Enqueue(ctx, entry); err != nil {
		if errors.Is(err, updatejournal.ErrResultConflict) {
			_ = e.Journal.MarkConflict(ctx, id.String(), "payload hash mismatch")
			return permanent(apierr.AckConflict, "result payload changed")
		}
		return err
	}
	return nil
}

// policyForResult is the desired-state config_generation already applied.
// A result is not posted until that generation is known. The job's
// generation is never substituted, and a desired state that was only
// received is not applied here.
func (e *Engine) policyForResult(ctx context.Context, c claimed) (decstr.U64, error) {
	applied, ok, err := e.Journal.AppliedConfig(ctx)
	if err != nil {
		return 0, err
	}
	// A non-zero generation, or an explicit zero from a verified envelope,
	// is the generation this job applied. It is never Intent.Generation.
	claimKnown := c.PolicyKnown || c.PolicyGeneration != 0
	if !ok {
		if !claimKnown {
			return 0, errors.New("updater: policy generation is not applied")
		}
		applied, _, err = e.Journal.AcceptDesired(ctx, c.PolicyGeneration, false, nil)
		return applied, err
	}
	// A claim generation above the applied one was only received. Keep the
	// applied generation. A claim generation at or below it is the one this
	// result applied, not a newer desired state accepted for a later job.
	if claimKnown && c.PolicyGeneration <= applied {
		return c.PolicyGeneration, nil
	}
	return applied, nil
}

// NoteAck records central acceptance. A late duplicate ACK is a no-op.
// A different payload hash is ACK_CONFLICT: the entry is kept and not resent.
func (e *Engine) NoteAck(ctx context.Context, resultID, payloadHash string, acceptedAsHistory bool, raw []byte) (duplicate bool, err error) {
	dup, err := e.Journal.AckResult(ctx, updatejournal.Ack{
		ResultID:          resultID,
		PayloadHash:       payloadHash,
		AcceptedAsHistory: acceptedAsHistory,
		Raw:               raw,
	})
	if errors.Is(err, updatejournal.ErrResultConflict) {
		_ = e.Journal.MarkConflict(ctx, resultID, "ACK payload hash mismatch")
		return false, permanent(apierr.AckConflict, "result")
	}
	return dup, err
}

// Flush sends pending results in order. Permanent HTTP rejections are retained
// for diagnosis and do not block later results. Retry-After defers the queue.
// Local success is not changed into acceptance here (§13.6 step 13).
// An unconfigured sink is an error, including when there is no queued work.
func (e *Engine) Flush(ctx context.Context) error {
	if e.Sender == nil {
		return permanent(apierr.ValidationFailed, "result_url is required for result delivery")
	}
	return e.withLockFor(ctx, "flush", func() error {
		if err := e.open(ctx); err != nil {
			return err
		}
		return e.flushLocked(ctx)
	})
}

func (e *Engine) flushLocked(ctx context.Context) error {
	pending, err := e.Journal.Pending(ctx, 50)
	if err != nil {
		return err
	}
	for _, ent := range pending {
		if !ent.RetryNotBefore.IsZero() && e.now().Before(ent.RetryNotBefore) {
			code, detail := apierr.RateLimited, "result retry deferred"
			if installerResultPending(ent.Payload, ent.LastHTTPStatus, ent.LastAPICode) {
				code, detail = apierr.ResourceNotFound, "central not yet accepting installer evidence"
			}
			return &DeliveryError{HTTPStatus: ent.LastHTTPStatus, APICode: ent.LastAPICode,
				RetryAt: ent.RetryNotBefore, Op: transient(code, detail)}
		}
		if ent.State == string(api.UpdateResultStateRolledBack) && locallyRecreatableResult(ent.Payload) {
			ent, err = e.Journal.PopulateCandidateHealth(ctx, ent.ResultID)
			if err != nil {
				return err
			}
		}
		ent, err = e.prepareInstallerResult(ctx, ent)
		if err != nil {
			return err
		}
		ack, conflict, err := e.Sender.Submit(ctx, ent.Payload)
		if conflict {
			status, code := updatejournal.OutboxConflict, string(apierr.AckConflict)
			if ack.HTTPStatus == 409 && ack.APICode == string(apierr.StateConflict) && ack.Reason == "job_id_mismatch" {
				status, code = updatejournal.OutboxRejected, ack.Reason
			}
			if err := e.Journal.RecordDeliveryFailure(ctx, ent.ResultID, updatejournal.DeliveryFailure{
				Status: status, HTTPStatus: ack.HTTPStatus, APICode: ack.APICode, ErrorCode: code,
			}); err != nil {
				return err
			}
			e.log().Warn("update result conflict", "http_status", ack.HTTPStatus, "api_code", ack.APICode, "reason", ack.Reason)
			continue
		}
		if err != nil {
			if asOp(err) == nil {
				err = transient(apierr.StoreUnavailable, "result submit")
			}
			failure := updatejournal.DeliveryFailure{Status: updatejournal.OutboxPending, ErrorCode: errCode(err)}
			var delivery *DeliveryError
			if errors.As(err, &delivery) {
				failure.HTTPStatus, failure.APICode, failure.RetryNotBefore = delivery.HTTPStatus, delivery.APICode, delivery.RetryAt
				if installerResultPending(ent.Payload, delivery.HTTPStatus, delivery.APICode) {
					// One attempt per flush, with the existing capped backoff.
					// Do not let an older central deployment reject durable local evidence.
					failure.RetryNotBefore = e.now().Add(e.backoff(ent.SendAttempts + 1))
					err = &DeliveryError{HTTPStatus: delivery.HTTPStatus, APICode: delivery.APICode,
						RetryAt: failure.RetryNotBefore, Op: transient(apierr.ResourceNotFound, "central not yet accepting installer evidence")}
					e.log().Info("central not yet accepting installer evidence", "http_status", delivery.HTTPStatus, "api_code", delivery.APICode)
				} else if delivery.rejected() {
					failure.Status = updatejournal.OutboxRejected
				}
			}
			if recordErr := e.Journal.RecordDeliveryFailure(ctx, ent.ResultID, failure); recordErr != nil {
				return recordErr
			}
			if failure.Status == updatejournal.OutboxRejected {
				e.log().Warn("update result rejected", "http_status", failure.HTTPStatus, "api_code", failure.APICode)
				continue
			}
			return err
		}
		raw := ack.Raw
		if len(raw) == 0 {
			raw = []byte("{}")
		}
		if _, err := e.NoteAck(ctx, ent.ResultID, ent.PayloadHash, ack.AcceptedAsHistory, raw); err != nil {
			return err
		}
	}
	return nil
}

func journalStageAPI(s updatejournal.Stage) api.UpdateStage {
	switch s {
	case updatejournal.StagePrepared:
		return api.UpdateStagePrepare
	case updatejournal.StageBlocked:
		return api.UpdateStageBlockForwarding
	case updatejournal.StageFinalSampled:
		return api.UpdateStageFinalSample
	case updatejournal.StageStopped:
		return api.UpdateStageStopServices
	case updatejournal.StageMigrated:
		return api.UpdateStageMigrate
	case updatejournal.StageSwitched:
		return api.UpdateStageSwitch
	case updatejournal.StageChecking:
		return api.UpdateStageCheck
	case updatejournal.StageRollingBack:
		return api.UpdateStageRollback
	default:
		return api.UpdateStageReport
	}
}

func utcSec(t time.Time) time.Time {
	if t.IsZero() {
		return t
	}
	return t.UTC().Truncate(time.Second)
}

func timePtr(t time.Time) *time.Time {
	if t.IsZero() {
		return nil
	}
	u := utcSec(t)
	return &u
}

func codePtr(c apierr.Code) *api.ErrorCode {
	if c == "" {
		return nil
	}
	v := api.ErrorCode(c)
	return &v
}

func stagePtr(s api.UpdateStage) *api.UpdateStage {
	if s == "" {
		return nil
	}
	v := s
	return &v
}

func parseID(s string) *uuid.UUID {
	if s == "" {
		return nil
	}
	id, err := uuid.Parse(s)
	if err != nil {
		return nil
	}
	return &id
}

func checkpointFromUsage(c UsageCheckpoint, newEpoch string) (*api.UpdateUsageCheckpoint, error) {
	out := &api.UpdateUsageCheckpoint{
		LastDurableEventSeq: c.LastDurableEventSeq,
		CentralAckedThrough: c.CentralAckedThrough,
		ClosedMeterEpochId:  presence.NewNullNullable[uuid.UUID](),
		NewMeterEpochId:     presence.NewNullNullable[uuid.UUID](),
	}
	if c.ClosedMeterEpochID != "" {
		id, err := uuid.Parse(c.ClosedMeterEpochID)
		if err != nil {
			return nil, permanent(apierr.CheckpointFailed, "closed meter epoch")
		}
		out.ClosedMeterEpochId.Set(id)
	}
	if newEpoch != "" {
		id, err := uuid.Parse(newEpoch)
		if err != nil {
			return nil, permanent(apierr.CheckpointFailed, "new meter epoch")
		}
		out.NewMeterEpochId.Set(id)
	}
	return out, nil
}

func decodeCheckpoint(raw []byte) (*api.UpdateUsageCheckpoint, error) {
	if len(raw) == 0 || bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return nil, nil
	}
	var c api.UpdateUsageCheckpoint
	if err := json.Unmarshal(raw, &c); err != nil {
		return nil, err
	}
	return &c, nil
}

func decodeHealth(raw []byte) (*api.UpdateHealth, error) {
	if len(raw) == 0 {
		return nil, nil
	}
	var h *api.UpdateHealth
	if err := json.Unmarshal(raw, &h); err != nil {
		return nil, err
	}
	return h, nil
}

// schemaAtLeast1 satisfies the result schema (minimum 1) when the node has
// not recorded a schema yet.
func schemaAtLeast1(n int) int {
	if n < 1 {
		return 1
	}
	return n
}

package updater

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"

	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/google/uuid"
)

// Retain keeps current, last_good, the active transaction's releases, open
// jobs and any release named by a result that is not yet acknowledged.
// It never deletes identity, state or the usage outbox (§13.7, §13.8).
func (e *Engine) Retain(ctx context.Context) error {
	return e.withLock(ctx, func() error {
		if e.Journal == nil {
			return nil
		}
		return e.retainLocked(ctx)
	})
}

func (e *Engine) retainLocked(ctx context.Context) error {
	keep := map[string]bool{}
	p, err := e.Journal.Pointers(ctx)
	if err != nil {
		return err
	}
	keep[p.CurrentRelease] = p.CurrentRelease != ""
	keep[p.LastGood] = p.LastGood != ""
	if txn, err := e.Journal.ActiveTxn(ctx); err == nil {
		keep[txn.ReleaseID] = txn.ReleaseID != ""
		keep[txn.PreviousReleaseID] = txn.PreviousReleaseID != ""
		keep[txn.LastGoodReleaseID] = txn.LastGoodReleaseID != ""
		keep[txn.RollbackReleaseID] = txn.RollbackReleaseID != ""
	}
	open, err := e.Journal.OpenJobs(ctx)
	if err != nil {
		return err
	}
	for _, job := range open {
		keep[job.ReleaseID] = job.ReleaseID != ""
	}
	box, err := e.Journal.Outbox(ctx)
	if err != nil {
		return err
	}
	for _, ent := range box {
		var res api.UpdateResult
		if json.Unmarshal(ent.Payload, &res) != nil {
			continue
		}
		if id, err := res.CurrentReleaseId.Get(); err == nil {
			keep[id.String()] = true
		}
		if id, err := res.PreviousReleaseId.Get(); err == nil {
			keep[id.String()] = true
		}
		if res.RequestedReleaseId != uuid.Nil {
			keep[res.RequestedReleaseId.String()] = true
		}
	}
	ids, err := e.Journal.ListReleases(ctx)
	if err != nil {
		return err
	}
	for _, id := range ids {
		if keep[id] {
			continue
		}
		dir := e.Layout.releaseDir(id)
		if err := os.RemoveAll(dir); err != nil {
			return err
		}
		if err := e.Journal.DeleteRelease(ctx, id); err != nil {
			return err
		}
	}
	arts, err := e.Journal.ListArtifacts(ctx)
	if err != nil {
		return err
	}
	for _, a := range arts {
		if keep[a.ReleaseID] {
			continue
		}
		if a.Path != "" {
			_ = os.Remove(a.Path)
		}
		if err := e.Journal.DeleteArtifact(ctx, a.SHA256); err != nil {
			return err
		}
	}
	// Drop partial downloads. Verified artifact files were handled above.
	entries, err := os.ReadDir(e.Layout.Staging)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	for _, ent := range entries {
		name := ent.Name()
		if len(name) > 8 && (name[len(name)-8:] == ".partial" || filepath.Ext(name) == ".meta") {
			_ = os.Remove(filepath.Join(e.Layout.Staging, name))
		}
	}
	// Drop probe-omission meta for finished apply transactions. An open
	// transaction and standalone revocation recovery (no txns row) stay.
	return e.Journal.PruneProbeOmissions(ctx)
}

package updater

import (
	"errors"
	"fmt"

	"github.com/TED-H-com/Freedom-VPN/pkg/apierr"
)

// OpError is a node-local update failure (§13.11). Detail is safe to log:
// no tokens, keys or member data. Retry means a later attempt may repeat
// the same step; permanent errors are not retried automatically (§13.4).
type OpError struct {
	Code   apierr.Code
	Detail string
	Retry  bool
}

func (e *OpError) Error() string {
	if e.Detail == "" {
		return "updater: " + string(e.Code)
	}
	return "updater: " + string(e.Code) + ": " + e.Detail
}

func opErr(code apierr.Code, detail string, retry bool) *OpError {
	return &OpError{Code: code, Detail: detail, Retry: retry}
}

func asOp(err error) *OpError {
	var op *OpError
	if errors.As(err, &op) {
		return op
	}
	return nil
}

// ErrNoWork means the verified desired state carries no update job.
var ErrNoWork = errors.New("updater: no authorized update")

// ErrCrashed is returned when a crash hook stops the process after a stage
// has been made durable. Callers must not clean up as if the step failed.
var ErrCrashed = errors.New("updater: injected crash")

// ErrSuperseded stops a queued or downloading job so a newer generation
// can run (§13.8).
var ErrSuperseded = errors.New("updater: superseded")

// ErrStateUnsafe means a migration cannot promise the previous release can
// read the state (§13.7). The outcome is recovery_required.
var ErrStateUnsafe = errors.New("updater: state is not readable by the previous release")

// ErrMembersBlocked means boot recovery left member forwarding off (§13.5,
// §13.9). The process exit code is 2. Local success is not implied.
var ErrMembersBlocked = errors.New("updater: member forwarding must stay blocked")

func permanent(code apierr.Code, detail string) *OpError {
	return opErr(code, detail, false)
}

func transient(code apierr.Code, detail string) *OpError {
	return opErr(code, detail, true)
}

func wrapCode(code apierr.Code, err error, retry bool) *OpError {
	if err == nil {
		return opErr(code, "", retry)
	}
	return opErr(code, fmt.Sprintf("%v", err), retry)
}

// Command fvpn-updater applies a verified desired state on one node
// (§13.4 to §13.9). It holds no release private key.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/TED-H-com/Freedom-VPN/node/internal/updatejournal"
	"github.com/TED-H-com/Freedom-VPN/node/updater"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprintln(stderr, "usage: fvpn-updater <run|recover|flush|status|apply|seed|version>")
		return 64
	}
	switch args[0] {
	case "version", "-h", "--help", "help":
		if args[0] == "version" {
			fmt.Fprintln(stdout, updater.Version)
			return 0
		}
		fmt.Fprintln(stderr, "usage: fvpn-updater <run|recover|flush|status|apply|seed|version>")
		return 0
	case "run", "recover", "flush", "apply", "seed":
		return command(args[0], args[1:], stderr)
	case "status":
		return status(args[1:], stdout, stderr)
	default:
		fmt.Fprintf(stderr, "fvpn-updater: unknown command %q\n", args[0])
		return 64
	}
}

func status(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("status", flag.ContinueOnError)
	fs.SetOutput(stderr)
	journal := fs.String("journal", "", "existing journal database file")
	config := fs.String("config", "", "updater config JSON")
	if err := fs.Parse(args); err != nil || fs.NArg() != 0 || (*journal != "" && *config != "") {
		return 64
	}
	path := *journal
	if *config != "" {
		cfg, err := updater.LoadConfig(*config)
		if err != nil {
			fmt.Fprintf(stderr, "fvpn-updater: %v\n", err)
			return 1
		}
		path = filepath.Join(cfg.Layout.Journal, updatejournal.FileName)
	}
	if path == "" {
		path = filepath.Join(updater.DefaultLayout().Journal, updatejournal.FileName)
	}
	snapshot, err := updatejournal.Snapshot(context.Background(), path)
	if err != nil {
		fmt.Fprintf(stderr, "fvpn-updater: status unavailable: %v\n", err)
		return 1
	}
	enc := json.NewEncoder(stdout)
	enc.SetIndent("", "  ")
	output := struct {
		updatejournal.SnapshotState
		WireCandidateHealth json.RawMessage `json:"candidate_health,omitempty"`
	}{SnapshotState: snapshot}
	if snapshot.State == "rolled_back" {
		output.WireCandidateHealth = snapshot.CandidateHealth
		if len(output.WireCandidateHealth) == 0 {
			output.WireCandidateHealth = json.RawMessage("null")
		}
	}
	if err := enc.Encode(output); err != nil {
		fmt.Fprintln(stderr, "fvpn-updater: write status failed")
		return 1
	}
	return 0
}

func command(name string, args []string, stderr io.Writer) int {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(stderr)
	cfgPath := fs.String("config", "", "updater config JSON (paths only, no keys)")
	pending := fs.String("pending", "", "installer pending-release.json to apply")
	var manifest, tree string
	if name == "seed" {
		fs.StringVar(&manifest, "manifest", "", "retained signed release envelope")
		fs.StringVar(&tree, "tree", "", "resolved current release directory to verify")
	}
	if err := fs.Parse(args); err != nil {
		return 64
	}
	if *cfgPath == "" {
		fmt.Fprintln(stderr, "fvpn-updater: -config is required")
		return 64
	}
	if name == "apply" && (strings.TrimSpace(*pending) == "" || fs.NArg() != 0) {
		fmt.Fprintln(stderr, "fvpn-updater: apply requires -config and -pending")
		return 64
	}
	if fs.NArg() != 0 || (name != "apply" && *pending != "") {
		fmt.Fprintln(stderr, "fvpn-updater: unexpected arguments")
		return 64
	}
	if name == "seed" && (strings.TrimSpace(manifest) == "" || strings.TrimSpace(tree) == "") {
		fmt.Fprintln(stderr, "fvpn-updater: seed requires -config, -manifest and -tree")
		return 64
	}
	cfg, err := updater.LoadConfig(*cfgPath)
	if err != nil {
		fmt.Fprintf(stderr, "fvpn-updater: %v\n", err)
		return 1
	}
	if name == "flush" && cfg.ResultURL == "" {
		fmt.Fprintln(stderr, "fvpn-updater: flush requires result_url")
		return 1
	}
	eng, err := cfg.Engine()
	if err != nil {
		fmt.Fprintf(stderr, "fvpn-updater: %v\n", err)
		return 1
	}
	defer eng.Close()
	eng.UseLog(slog.New(slog.NewJSONHandler(stderr, nil)))
	ctx := context.Background()
	var runErr error
	switch name {
	case "run":
		runErr = eng.Run(ctx)
	case "recover":
		runErr = eng.Recover(ctx)
	case "apply":
		runErr = eng.ApplyPending(ctx, *pending)
	case "seed":
		runErr = eng.Seed(ctx, manifest, tree)
	default:
		runErr = eng.Flush(ctx)
	}
	if runErr != nil && (name == "apply" || !errors.Is(runErr, updater.ErrMembersBlocked)) {
		fmt.Fprintf(stderr, "fvpn-updater: %v\n", runErr)
	}
	return updater.ExitCode(runErr)
}

// Package nodelock is the node-wide exclusive update lock of §13.5: the agent,
// the manual installer and the updater take the same flock before they change
// the version pointer, the state schema or product services. Contention is
// reported as busy (UPDATE_BUSY), never waited on forever.
package nodelock

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/google/uuid"
)

// DefaultPath is the default lock file (§4 node paths).
const DefaultPath = "/var/lib/vpn-node/update.lock"

// ErrBusy means another process holds the lock (UPDATE_BUSY, §13.11).
var ErrBusy = errors.New("UPDATE_BUSY: node update lock is held by another process")

// Lock is a held exclusive flock. The descriptor stays open until Release.
type Lock struct {
	f *os.File
}

// holder is the metadata written only after flock succeeds (D-034d).
// StartTime is field 22 of /proc/<pid>/stat, in clock ticks since boot.
type holder struct {
	PID       int    `json:"pid"`
	BootID    string `json:"boot_id"`
	StartTime int64  `json:"start_time"`
}

// TryAcquire takes LOCK_EX|LOCK_NB before it writes holder metadata. It
// returns ErrBusy when the lock is held elsewhere and does not remove the
// file. A crashed holder is released by the kernel when its descriptor
// closes. Stale detection compares the recorded boot id, pid and process
// start time. A stale record does not justify deleting a file another
// process still has locked: the error names the reason and the flock stays.
func TryAcquire(path string) (*Lock, error) {
	return tryAcquire(path, "", "/proc/sys/kernel/random/boot_id")
}

func tryAcquire(path, fallback, bootPath string) (*Lock, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, err
	}
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		if errors.Is(err, syscall.EWOULDBLOCK) {
			h, ok := readHolder(f)
			_ = f.Close()
			if ok {
				if reason, stale := holderStaleReason(h, bootID(bootPath, fallback)); stale {
					// The record is stale, but flock is still held. Do not unlink.
					return nil, fmt.Errorf("%w: %s", ErrBusy, reason)
				}
			}
			return nil, ErrBusy
		}
		_ = f.Close()
		return nil, fmt.Errorf("flock: %w", err)
	}
	if err := writeHolder(f, bootID(bootPath, fallback)); err != nil {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
		return nil, err
	}
	return &Lock{f: f}, nil
}

func readBootID() string {
	return bootID("/proc/sys/kernel/random/boot_id", "")
}

func bootID(path, fallback string) string {
	b, err := os.ReadFile(path)
	if err != nil {
		return fallback
	}
	id, err := uuid.Parse(strings.TrimSpace(string(b)))
	if err != nil || id == uuid.Nil {
		return fallback
	}
	return id.String()
}

func readHolder(f *os.File) (holder, bool) {
	st, err := f.Stat()
	if err != nil || st.Size() == 0 || st.Size() > 1<<20 {
		return holder{}, false
	}
	buf := make([]byte, st.Size())
	n, err := f.ReadAt(buf, 0)
	if err != nil || n == 0 {
		return holder{}, false
	}
	var h holder
	if json.Unmarshal(buf[:n], &h) != nil {
		return holder{}, false
	}
	return h, true
}

func writeHolder(f *os.File, boot string) error {
	start, ok := processStartTime(os.Getpid())
	if !ok {
		return errors.New("nodelock: process start time")
	}
	raw, err := json.Marshal(holder{PID: os.Getpid(), BootID: boot, StartTime: start})
	if err != nil {
		return err
	}
	if err := f.Truncate(0); err != nil {
		return err
	}
	if _, err := f.WriteAt(raw, 0); err != nil {
		return err
	}
	return f.Sync()
}

// holderStale reports whether a recorded holder cannot still be this boot's
// live process. A different boot id is stale even when the pid number has
// been reused. A dead pid is stale on the same boot. The same pid is stale
// when its /proc start time differs, which is how a reused pid is told apart
// from the process that took the lock.
func holderStale(h holder, boot string) bool {
	_, stale := holderStaleReason(h, boot)
	return stale
}

// holderStaleReason names why a record is stale: "boot id", "pid",
// "process" or "start time". A live flock holder is not stale.
func holderStaleReason(h holder, boot string) (string, bool) {
	if h.BootID != boot {
		return "boot id", true
	}
	if h.PID <= 0 {
		return "pid", true
	}
	if syscall.Kill(h.PID, 0) != nil {
		return "process", true
	}
	start, ok := processStartTime(h.PID)
	if !ok {
		return "process", true
	}
	if h.StartTime == 0 || h.StartTime != start {
		return "start time", true
	}
	return "", false
}

// processStartTime reads field 22 of /proc/<pid>/stat (starttime, clock ticks
// since boot). The command name is in parentheses and may itself contain
// spaces and parentheses, so the fields are counted after the last ')'.
func processStartTime(pid int) (int64, bool) {
	b, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	if err != nil {
		return 0, false
	}
	return parseStatStart(string(b))
}

func parseStatStart(s string) (int64, bool) {
	i := strings.LastIndex(s, ")")
	if i < 0 || i+2 >= len(s) {
		return 0, false
	}
	fields := strings.Fields(s[i+2:])
	// Field 22 is index 19 of the fields that follow the command name.
	if len(fields) <= 19 {
		return 0, false
	}
	n, err := strconv.ParseInt(fields[19], 10, 64)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

// Acquire retries TryAcquire with a fixed interval until attempts run out or
// ctx ends (bounded wait, §13.11 UPDATE_BUSY).
func Acquire(ctx context.Context, path string, attempts int, interval time.Duration) (*Lock, error) {
	return AcquireWithBootID(ctx, path, attempts, interval, "")
}

// AcquireWithBootID uses fallback only if the kernel boot id is unreadable.
// It otherwise has the same bounded contention behavior as Acquire.
func AcquireWithBootID(ctx context.Context, path string, attempts int, interval time.Duration, fallback string) (*Lock, error) {
	if attempts < 1 {
		attempts = 1
	}
	var last error
	for i := 0; i < attempts; i++ {
		l, err := tryAcquire(path, fallback, "/proc/sys/kernel/random/boot_id")
		if err == nil {
			return l, nil
		}
		last = err
		if !errors.Is(err, ErrBusy) {
			return nil, err
		}
		if i == attempts-1 {
			break
		}
		t := time.NewTimer(interval)
		select {
		case <-ctx.Done():
			t.Stop()
			return nil, ctx.Err()
		case <-t.C:
		}
	}
	return nil, last
}

// Release drops the lock. It is safe to call more than once.
func (l *Lock) Release() error {
	if l == nil || l.f == nil {
		return nil
	}
	err := syscall.Flock(int(l.f.Fd()), syscall.LOCK_UN)
	cerr := l.f.Close()
	l.f = nil
	if err != nil {
		return err
	}
	return cerr
}

package agent

import (
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/google/uuid"
)

// D-157 is one opportunity per verified closed Apply, not per empty lease or
// report. It is process-local: restart does not recreate a closed Apply receipt.
type recoveryRenewal struct {
	armed    bool
	reportID uuid.UUID
	accepted bool
}

func (e *Engine) recoveryRenewalEligible() bool {
	return e.closedRecoveryHeld && !e.serving && e.applyError == nil &&
		!e.revoked && !e.identityFrozen && !e.freezeUncertain && e.storageOK &&
		!e.quarantinePending && !e.memberPathPending && !e.dependencyMissing &&
		e.appliedGen > 0 && e.desiredOK && !e.desiredExpired && e.desired != nil &&
		uint64(e.desired.ConfigGeneration) == e.appliedGen && e.leaseGrantless() &&
		!e.leaseBehindApplied()
}

// Bind to a newly queued report from this recovery. An old queued report, even
// at the same generation, cannot arm a later recovery's opportunity.
func (e *Engine) noteRecoveryReport(rep api.ObservationReport) {
	r := &e.closedRecoveryRenewal
	if !r.armed || r.reportID != uuid.Nil || !e.recoveryRenewalEligible() {
		return
	}
	gen, err := rep.AppliedConfigGeneration.Get()
	if err != nil || uint64(gen) != e.appliedGen || rep.MemberForwardingEnabled ||
		rep.SafetyStatus != api.SafetyStatusPassed || rep.ProvisioningState != api.ProvisioningStateReady ||
		rep.Netbird.Backend != api.ObservationReportNetbirdBackendKernel || !rep.Netbird.PeerId.IsNull() {
		return
	}
	// These are central's synchronous readiness evidence requirements. A failed
	// meter path is never the D-067 awaiting-grants exception.
	internet, awaiting := false, false
	for _, reason := range rep.ForwardingBlockReasons {
		awaiting = awaiting || reason == api.ForwardingBlockReasonAwaitingMemberGrants
	}
	for _, check := range rep.Checks {
		if check.Name == api.NodeCheckNameInternetOnly {
			internet = check.Status == api.HealthCheckStatusPassed
		}
		if check.Name == api.NodeCheckNameMeterPath && check.Status == api.HealthCheckStatusFailed {
			return
		}
	}
	for _, err := range rep.Errors {
		switch err.Code {
		case api.ErrorCodeISOLATIONPOLICYINVALID, api.ErrorCodeISOLATIONBASELINEMISSING, api.ErrorCodeMETERPATHINVALID:
			return
		}
	}
	if internet && awaiting {
		r.reportID = rep.ReportId
	}
}

func (e *Engine) acceptRecoveryReport(rep api.ObservationReport, accepted api.ObservationAccepted) {
	r := &e.closedRecoveryRenewal
	if r.armed && r.reportID != uuid.Nil && rep.ReportId == r.reportID &&
		accepted.ReportId == rep.ReportId && bool(accepted.Accepted) &&
		(accepted.IdentityFrozen == nil || !*accepted.IdentityFrozen) && e.recoveryRenewalEligible() {
		r.accepted = true
	}
}

func (e *Engine) earlyRecoveryRenewal() bool {
	return e.closedRecoveryRenewal.armed && e.closedRecoveryRenewal.accepted && e.recoveryRenewalEligible()
}

