)

func (e *Engine) observe(ctx context.Context) error {
	if !e.enrolled || e.nodeID == uuid.Nil {
		return nil
	}
	wall := e.clock.Wall()
	interval := time.Duration(e.cfg.ObservationSeconds) * time.Second
	e.updateStaleHold()
	state := e.observationState()
	due := e.lastObs.IsZero() || wall.Sub(e.lastObs) >= interval || e.serving != e.lastServing || state != e.lastObservationState
	if !due || e.outboxFull {
		return nil
	}
	// Retain the first deciding body through backoff. Repeated copies of the
	// same pending state add no evidence; transitions always get their own ID.
	if state == e.lastObservationState {
		items, err := e.store.Pending(ctx)
		if err != nil {
			return err
		}
		if len(items) > 0 {
			return nil
		}
	}
	rep, err := e.report(ctx, wall.UTC())
	if err != nil {
		return err
	}
	raw, err := json.Marshal(rep)
	if err != nil {
		return err
	}
	if err := e.store.Enqueue(ctx, rep.ReportId, raw, wall.UTC()); err != nil {
		e.storageOK = false
		return err
	}
	e.noteRecoveryReport(rep)
	e.lastObs = wall
	e.lastServing = e.serving
	e.lastObservationState = state
	return nil
}

func (e *Engine) report(ctx context.Context, at time.Time) (api.ObservationReport, error) {
	id, err := uuid.NewV7()
	if err != nil {
		return api.ObservationReport{}, err
	}
	appliedGen := presence.NewNullNullable[decstr.U64]()
	appliedBind := presence.NewNullNullable[decstr.U64]()
	appliedPol := presence.NewNullNullable[api.PolicyRefs]()
	if !e.identityFrozen && !e.freezeUncertain && e.appliedGen > 0 {
		appliedGen = presence.NewNullableWithValue(decstr.U64(e.appliedGen))
		if s := e.appliedSnapshot; s != nil && uint64(s.Generation) == e.appliedGen {
			appliedBind = presence.NewNullableWithValue(s.BindingRevision)
			appliedPol = presence.NewNullableWithValue(s.PolicyRefs)
		}
	}
	release := presence.NewNullNullable[uuid.UUID]()
	if rid := e.cfg.ReleaseUUID(); rid != uuid.Nil {
		release = presence.NewNullableWithValue(rid)
	}
	lastGood := presence.NewNullNullable[uuid.UUID]()
	if e.appliedGen > 0 {
		lastGood = release
	}
	exp := presence.NewNullNullable[time.Time]()
	lid := presence.NewNullNullable[uuid.UUID]()
	if e.lease != nil {
		exp = presence.NewNullableWithValue(e.lease.ExpiresAt.UTC())
		lid = presence.NewNullableWithValue(e.lease.LeaseId)
	}
	d := e.reportingDecision()
	reasons := d.Reasons
	if reasons == nil {
		reasons = []api.ForwardingBlockReason{}
	}
	errs := slices.Clone(d.Errors)
	if errs == nil {
		errs = []api.NodeError{}
	}
	checks := slices.Clone(d.Checks)
	if checks == nil {
		checks = []api.NodeCheck{}
	}
	backend := api.ObservationReportNetbirdBackendUnknown
	switch e.cfg.NetbirdBackend {
	case "kernel":
		backend = api.ObservationReportNetbirdBackendKernel
	case "userspace":
		backend = api.ObservationReportNetbirdBackendUserspace
	}
	rep := api.ObservationReport{
		AgentVersion:            e.cfg.AgentRelease,
		AppliedBindingRevision:  appliedBind,
		AppliedConfigGeneration: appliedGen,
		AppliedPolicyRefs:       appliedPol,
		BootId:                  e.bootID,
		Checks:                  checks,
		CurrentReleaseId:        release,
		DataHealth:              reportedHealth(d.DataHealth),
		Errors:                  errs,
		ForwardingBlockReasons:  reasons,
		LastGoodReleaseId:       lastGood,
		MemberForwardingEnabled: e.serving,
		NodeId:                  e.nodeID,
		NodeIncarnationId:       e.incID,
		ObservedAt:              at,
		ProvisioningState:       d.Provisioning,
		ReportId:                id,
		SafetyStatus:            d.Safety,
	}
	rep.Lease.ExpiresAt = exp
	rep.Lease.LeaseId = lid
	rep.Netbird.Backend = backend
	rep.Netbird.PeerId = presence.NewNullNullable[string]()
	rep.Netbird.Version = presence.NewNullNullable[string]()
	e.attachServingRead(&rep)
	e.attachContainment(&rep, at)
	e.attachStaleHold(&rep)
	if f := e.failedCandidate; f != nil {
		err := f.Error
		err.Stage = "apply_candidate"
		err.Message = fmt.Sprintf("candidate_generation=%d verified=false", f.Generation)
		rep.Errors = append(rep.Errors, err)
	}
	e.attachUsage(ctx, &rep)
	e.attachUpdate(ctx, &rep)
	if e.dnsEv != nil {
		rep.DnsPolicyEvidence = presence.NewNullableWithValue(*e.dnsEv)
	}
	return rep, nil
}

// The ACK describes the last completed Apply or baseline. Keep its document
// refs even when a newer desired document has replaced the live input. This is
// observation provenance, never authorization to serve or to adopt a model.
type appliedSnapshot struct {
	Generation      decstr.U64     `json:"generation"`
	BindingRevision decstr.U64     `json:"binding_revision"`
	PolicyRefs      api.PolicyRefs `json:"policy_refs"`
}

func snapshotOf(ds *api.DesiredState) appliedSnapshot {
	return appliedSnapshot{ds.ConfigGeneration, ds.BindingRevision, ds.PolicyRefs}
}

func (e *Engine) loadAppliedSnapshot(ctx context.Context) error {
	raw, ok, err := e.store.Meta(ctx, agentstore.AppliedSnapshotKey)
	if err != nil {
		return err
	}
	if ok {
		var s appliedSnapshot
		if err := json.Unmarshal([]byte(raw), &s); err != nil {
			return err
		}
		if uint64(s.Generation) == e.appliedGen {
			e.appliedSnapshot = &s
		}
	} else if e.appliedGen > 0 && e.desired != nil && uint64(e.desired.ConfigGeneration) == e.appliedGen {
		// Upgrade: only an authenticated matching document can reconstruct
		// the old ACK. A newer document cannot supply missing historical refs.
		s := snapshotOf(e.desired)
		raw, err := json.Marshal(s)
		if err != nil {
			return err
		}
		if err := e.store.MarkAppliedSnapshot(ctx, e.appliedGen, string(raw)); err != nil {
			return err
		}
		e.appliedSnapshot = &s
	}
	return nil
}

// attachUpdate reads the updater journal once for this report. A null
// generation (no file, no recorded job, or a snapshot error) leaves the
// update members null. The read is not cached and does not fail the report.
// current_release_id defaults to the running binary. Only a completed local
// switch or rollback with a valid job ID can override it from the journal.
func (e *Engine) attachUpdate(ctx context.Context, rep *api.ObservationReport) {
	rep.Update.Generation = presence.NewNullNullable[decstr.U64]()
	rep.Update.JobId = presence.NewNullNullable[uuid.UUID]()
	rep.Update.Stage = presence.NewNullNullable[api.UpdateStage]()
	rep.Update.State = presence.NewNullNullable[api.UpdateJobState]()
	if e.cfg.UpdaterJournal == "" {
		return
	}
	snap, err := updatejournal.Snapshot(ctx, e.cfg.UpdaterJournal)
	e.noteUpdateSnapshot(err)
	if err != nil || snap.Generation == nil {
		return
	}
	rep.Update.Generation = presence.NewNullableWithValue(*snap.Generation)
	if id, perr := uuid.Parse(snap.JobID); perr == nil && id != uuid.Nil {
		rep.Update.JobId = presence.NewNullableWithValue(id)
	}
	if stage := api.UpdateStage(snap.Stage); stage.Valid() {
		rep.Update.Stage = presence.NewNullableWithValue(stage)
	}
	if state := api.UpdateJobState(snap.State); state.Valid() {
		rep.Update.State = presence.NewNullableWithValue(state)
	}
	current := presence.NewNullableWithValue(e.cfg.ReleaseUUID())
	_, jobErr := rep.Update.JobId.Get()
	if jobErr == nil && (snap.JournalStage == updatejournal.StageLocallySucceeded || snap.JournalStage == updatejournal.StageRolledBack) {
		if id, perr := uuid.Parse(snap.CurrentRelease); perr == nil && id != uuid.Nil {
			current = presence.NewNullableWithValue(id)
		}
	}
	last := presence.NewNullNullable[uuid.UUID]()
	if id, perr := uuid.Parse(snap.LastGoodRelease); perr == nil && id != uuid.Nil {
		last = presence.NewNullableWithValue(id)
	}
	rep.CurrentReleaseId = current
	rep.LastGoodReleaseId = last
}

func (e *Engine) noteUpdateSnapshot(err error) {
	reason := updateSnapshotReason(err)
	if reason == e.updateSnapReason {
		return
	}
	e.updateSnapReason = reason
	if reason == "" || e.log == nil {
		return
	}
	e.log.Warn("updater journal snapshot", "reason", reason)
}

// updateSnapshotReason is a short class. It is safe to log. Snapshot errors
// can carry a path or a schema number, and those stay out of the log.
func updateSnapshotReason(err error) string {
	if err == nil {
		return ""
	}
	switch {
	case errors.Is(err, os.ErrNotExist):
		return "missing"
	case errors.Is(err, context.Canceled):
		return "canceled"
	case errors.Is(err, context.DeadlineExceeded):
		return "deadline"
	}
	msg := err.Error()
	switch {
	case strings.Contains(msg, "unsupported snapshot schema"):
		return "unsupported_schema"
	case strings.Contains(msg, "regular database file"):
		return "not_a_file"
	default:
		return "unreadable"
	}
}

func reportedHealth(h api.DataHealth) api.DataHealth {
	if !h.Valid() {
		return api.DataHealthUnknown
	}
	return h
}

func (e *Engine) flush(ctx context.Context) error {
	if e.clock.Mono() < e.observationRetryAt {
		return nil
	}
	items, err := e.store.Pending(ctx)
	if err != nil {
		e.storageOK = false
		return err
	}
	e.outboxFull = len(items) >= 32
	for _, item := range items {
		if err := controlContext(ctx).Err(); err != nil {
			return err
		}
		var rep api.ObservationReport
		if err := json.Unmarshal(item.Payload, &rep); err != nil {
			_ = e.store.MarkConflict(ctx, item.ReportID)
			continue
		}
		if e.identityFrozen && e.freezeDurable && (rep.MemberForwardingEnabled || !rep.AppliedConfigGeneration.IsNull()) {
			_ = e.store.MarkConflict(ctx, item.ReportID)
			continue
		}
		// Persist uncertainty before sending. A process can die after central
		// accepts a freeze but before the response reaches local storage.
		if err := e.store.BumpAttempt(ctx, item.ReportID, "in_flight"); err != nil {
			e.storageOK = false
			return err
		}
		accepted, err := e.client.Observe(controlContext(ctx), item.ReportID, rep)
		if err == nil {
			e.observationFailures, e.observationRetryAt = 0, 0
			if accepted.IdentityFrozen != nil && *accepted.IdentityFrozen {
				e.freezeIdentity(ctx)
				if !e.freezeDurable {
					return nil
				}
			}
			e.acceptRecoveryReport(rep, accepted)
			if serr := e.store.MarkAccepted(ctx, item.ReportID, e.clock.Wall().UTC()); serr != nil {
				e.storageOK = false
			}
			continue
		}
		if isRevoked(err) {
			e.markRevoked(ctx)
			return nil
		}
		var se *controlclient.StatusError
		if errors.As(err, &se) && (se.Status == 409 || se.Status == 422) {
			_ = e.store.MarkConflict(ctx, item.ReportID)
			continue
		}
		_ = e.store.BumpAttempt(ctx, item.ReportID, safeErr(err))
		e.observationFailures++
		wait := time.Second
		for i := 1; i < e.observationFailures && wait < 30*time.Second; i++ {
			wait *= 2
		}
		wait = min(time.Minute, wait+observationJitter(wait))
		if se != nil {
			wait = max(wait, se.RetryAfter)
		}
		e.observationRetryAt = e.clock.Mono() + wait
		return nil // One failed request per slot, even with a full outbox.
	}
	remaining, err := e.store.Pending(ctx)
	if err != nil {
		return err
	}
	e.freezeUncertain = false
	for _, item := range remaining {
		if item.Attempts > 0 {
			e.freezeUncertain = true
		}
	}
	return nil
}

func observationJitter(wait time.Duration) time.Duration {
	span := wait / 10
	if span <= 0 {
		return 0
	}
	// Nanosecond ranges need more than 16 bits of entropy; otherwise every
	// node retries within a few microseconds of the same lower bound.
	var b [8]byte
	if _, err := rand.Read(b[:]); err != nil {
		return 0
	}
	return time.Duration(binary.LittleEndian.Uint64(b[:])%uint64(2*span+1)) - span
}

// Timestamps and read-at detail change every tick. The semantic transition
// includes every check status/code and block reason, including provisional.
func (e *Engine) observationState() string {
	d := e.reportingDecision()
	type check struct {
		Name   api.NodeCheckName
		Status api.HealthCheckStatus
		Code   string
	}
	cs := make([]check, 0, len(d.Checks))
	for _, c := range d.Checks {
		code, _ := c.ErrorCode.Get()
		cs = append(cs, check{c.Name, c.Status, string(code)})
	}
	// A rejected candidate is not an applied ACK. Keep its transition even
	// while older bodies await retry. Exclude read times/diagnostic durations
	// so identical pending evidence is still coalesced.
	var candidate uint64
	var code api.ErrorCode
	if f := e.failedCandidate; f != nil {
		candidate, code = f.Generation, f.Error.Code
	}
	var readGeneration uint64
	var verified bool
	if r := e.servingRead; r != nil {
		readGeneration, verified = r.Generation, r.Verified
	}
	var containment any
	if c := e.containment; c != nil {
		v := *c
		v.ReadAt = time.Time{}
		containment = []any{c.Generation, v}
	}
	b, _ := json.Marshal([]any{e.serving, e.appliedGen, d.Provisioning, d.Safety, d.Reasons, cs,
		candidate, code, readGeneration, verified, containment, e.staleHold.steps > 0, e.staleHold.alarm})
	return string(b)
}

// An Apply failure can precede the verifier. Report the attempted generation
// without pretending that a missing verifier read supplied fresh tc evidence.
type failedCandidate struct {
	Generation uint64
	Error      api.NodeError
}

// A cached serving decision can precede a failed local persistence/withdrawal.
// Report the current cause when one exists. The zero decision before the first
// evaluation has no checks and legitimately retains the heartbeat's "-".
func (e *Engine) reportingDecision() Decision {
	d := e.decision
	if !e.serving && len(d.Reasons) == 0 && len(d.Checks) != 0 {
		current := Decide(e.input())
		if len(current.Reasons) != 0 {
			current.Errors = append(current.Errors, d.Errors...)
			return current
		}
	}
	return d
}

package agent

import (
	"context"
	"errors"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/enforce"
	"github.com/google/uuid"
)

func (e *Engine) stepInterval() time.Duration {
	interval := e.heartbeatInterval()
	if poll := time.Duration(e.cfg.PollSeconds) * time.Second; poll > 0 {
		interval = min(interval, poll)
	}
	return interval
}

func (e *Engine) remainingStepDelay(started, interval time.Duration) time.Duration {
	return max(0, interval-max(0, e.clock.Mono()-started))
}

// Serving retains its start-anchored watchdog cadence. Grant-less steps are
// already closed: use the renewal deadline directly rather than racing it
// against a poll anchored before that request was sent.
func (e *Engine) runStepDelay(started, interval time.Duration) time.Duration {
	if e.leaseGrantless() && !e.serving {
		return e.nextStepDelay(interval)
	}
	return min(e.nextStepDelay(interval), e.remainingStepDelay(started, interval))
}

// Each read gets at most half the shorter heartbeat/poll cadence, capped at
// one second. Slow or canceled reads cannot refresh a cached serving claim.
func (e *Engine) servingReadTimeout() time.Duration {
	return min(time.Second, e.stepInterval()/2)
}

func (e *Engine) verifyServingModel(ctx context.Context, model enforce.Model, assignments map[uuid.UUID]uint16) bool {
	// Liveness cancellation may stop control work, but cannot itself prove a
	// kernel defect. This independent bounded read still fails on real drift
	// or its own timeout, including when shutdown interrupts a Step read.
	readCtx, cancel := context.WithTimeout(localContext(ctx), e.servingReadTimeout())
	defer cancel()
	evidence, err := e.plane.VerifyServing(readCtx, model, assignments)
	// Even an executor that returns success at the deadline cannot supply
	// fresh evidence. Keep a specific CheckError when one accompanied it.
	err = errors.Join(err, readCtx.Err())
	e.measureTiming(evidence, "live")
	e.retainServingRead(evidence, model.Generation, e.clock.Wall(), "live", err == nil)
	if err == nil {
		return true
	}
	if !e.repairGeneration(ctx, model, evidence, err) {
		e.rejectServing(ctx, model, evidence, err)
	}
	return false
}

// A replaced generation is repairable with the already-authorized lease.
// Queue the truthful failed read BEFORE repair can replace its evidence. No
// control I/O, baseline, or new lease is required on the successful path.
// Other failures (especially foreign tc) still follow quarantine/withdrawal.
func (e *Engine) repairGeneration(ctx context.Context, model enforce.Model, evidence enforce.ServingEvidence, err error) bool {
	var check *enforce.CheckError
	if e.meter == nil || e.planeLocked || e.repairing || ctx.Err() != nil || !errors.As(err, &check) || check.Reason != enforce.ReasonGenerationMismatch {
		return false
	}
	e.refreshDesired()
	in := e.input()
	in.ApplyError = nil
	d := Decide(in)
	if !d.Serve || e.leaseBoot != e.bootID || e.appliedGen != model.Generation || d.Model.Generation != model.Generation {
		return false
	}
	e.repairing = true
	defer func() { e.repairing = false }()
	e.noteApply(err)
	if e.kernel != nil && e.expectServing.Load() {
		e.kernel.rejectedGeneration()
	}
	e.serving = false
	e.decision = Decide(e.input())
	e.lastObs = time.Time{}
	if err := e.observe(ctx); err != nil {
		return false
	}
	if err := e.enforce(ctx, d); err != nil {
		return false
	}
	if !e.serving {
		return false
	}
	e.decision = Decide(e.input())
	e.beat()
	return true
}

func (e *Engine) verifyCurrentServing(ctx context.Context) bool {
	if !e.serving {
		return true
	}
	if e.usagePersist || e.retainedPending || !e.baselineOK {
		e.withdraw(ctx)
		e.decision = Decide(e.input())
		e.lastObs = time.Time{}
		return false
	}
	if e.expireServing(ctx) {
		return false
	}
	if e.appliedModel == nil {
		e.rejectServing(ctx, enforce.Model{}, enforce.ServingEvidence{}, errors.New("missing applied model"))
		return false
	}
	if !e.verifyServingModel(ctx, *e.appliedModel, e.appliedAssignments) {
		return false
	}
	// The live read may straddle expiry. It proves rules, not a renewed lease.
	if e.expireServing(ctx) {
		return false
	}
	// Publish the verified state before synchronous control work can stall.
	e.beat()
	return true
}

func (e *Engine) expireServing(ctx context.Context) bool {
	if !e.serving || (e.policyExpires > 0 && e.clock.Mono() < e.policyExpires) {
		return false
	}
	e.refreshDesired()
	e.decision = Decide(e.input())
	if e.policyExpires > 0 && e.decision.Serve {
		// A binding boundary is a wake, not a node withdrawal. Its kernel
		// timeout already stopped admission; enforce applies survivors.
		return false
	}
	cleanup, cancel := context.WithTimeout(localContext(ctx), 5*time.Second)
	defer cancel()
	e.withdraw(cleanup)
	e.decision = Decide(e.input())
	e.lastObs = time.Time{}
	return true
}

// rejectServing is the common withdrawal point for Apply and live reads.
// Quarantine precedes withdrawal and always uses the retained applied model.
func (e *Engine) rejectServing(ctx context.Context, model enforce.Model, evidence enforce.ServingEvidence, err error) {
	e.noteApply(err)
	var check *enforce.CheckError
	if e.kernel != nil && e.expectServing.Load() && errors.As(err, &check) && check.Reason == enforce.ReasonGenerationMismatch {
		// The real live read found a replaced/cleared ruleset. Retain that
		// incident before our planned baseline disables reset detection.
		e.kernel.rejectedGeneration()
	}
	// A failed/canceled read must still be able to install the baseline.
	cleanupCtx, cancel := cleanupBudget(ctx)
	defer cancel()
	if errors.As(err, &check) && check.Reason == enforce.ReasonTCForeignFilter {
		e.quarantinePending = true
		e.memberPathPending = true
		e.recordForeign(evidence)
		if e.containment.ReadAt.IsZero() {
			e.containment.Generation = model.Generation
			e.containment.ReadAt = e.applyError.ObservedAt
			if r := e.servingRead; r != nil && !r.Verified && r.Generation == model.Generation {
				e.containment.ReadAt = r.At
			}
		}
	}
	if e.quarantinePending {
		e.quarantine(cleanupCtx)
	}
	e.withdraw(cleanupCtx)
	e.decision = Decide(e.input())
	e.lastObs = time.Time{}
}

// finishServingStep runs on every return, including control I/O cancellation
// and a busy apply lock. Write the heartbeat immediately after the live read;
// a failure also queues and delivers a corrected observation on this step.
func (e *Engine) finishServingStep(ctx context.Context) {
	// SIGTERM can interrupt control I/O mid-Step. A canceled command is not
	// a kernel observation: perform the bounded final read independently so
	// normal process replacement cannot manufacture a foreign-tc quarantine.
	ctx = localContext(ctx)
	ok := e.verifyCurrentServing(ctx)
	if !e.serving {
		e.auditBlocked(ctx)
	}
	if !e.serving && e.quarantinePending {
		e.quarantine(ctx)
		e.decision = Decide(e.input())
		ok = false
	}
	changed := e.updateStaleHold()
	e.beat()
	if !ok || !e.serving || changed || (e.identityFrozen && e.lastObs.IsZero()) {
		_ = e.observe(ctx)
		_ = e.flush(ctx)
	}
}

// A baseline is not proof that an ingress redirect disappeared. Audit the
// retained member path even on revoked, canceled and already-blocked returns.
func (e *Engine) auditBlocked(ctx context.Context) {
	if e.appliedModel == nil {
		return
	}
	readCtx, cancel := context.WithTimeout(localContext(ctx), e.servingReadTimeout())
	defer cancel()
	ev, err := e.plane.VerifyServing(readCtx, *e.appliedModel, e.appliedAssignments)
	e.measureTiming(ev, "blocked_audit")
	e.retainTCReadback(ev)
	var check *enforce.CheckError
	if errors.As(err, &check) && check.Reason == enforce.ReasonTCForeignFilter {
		// An unreadable tc attachment on a proven absent member link is
		// missing topology, not a foreign filter. The verified baseline stays
		// closed; no containment latch may obstruct the later clean Apply.
		if e.missingMemberInterface(readCtx, ev) {
			return
		}
		e.noteApply(err)
		if e.containment == nil || len(e.containment.TC) == 0 {
			e.recordForeign(ev)
			e.containment.Generation = e.appliedModel.Generation
			e.containment.ReadAt = e.clock.Wall().UTC()
		}
		e.quarantinePending, e.memberPathPending = true, true
	}
	if ev.Quarantined {
		e.quarantinePending, e.memberPathPending = true, true
	}
}

// Retained for containment auditing and the original installation time sample
// during verified same-boot adoption; never used as desired authorization.
type retainedApplied struct {
	Model       enforce.Model        `json:"model"`
	Assignments map[uuid.UUID]uint16 `json:"assignments"`
}

// One shared budget, independent of the number of endpoints and retries.
func (e *Engine) controlPassTimeout() time.Duration {
	stale := time.Duration(e.cfg.WatchdogStaleSeconds) * time.Second
	if stale <= 0 {
		stale = 30 * time.Second
	}
	return min(5*time.Second, stale/3)
}

// The budget constrains network requests only. Local persistence and cleanup
// use the caller context, so a control outage is not reported as disk failure.
type controlBudgetKey struct{}

func controlContext(ctx context.Context) context.Context {
	if budget, ok := ctx.Value(controlBudgetKey{}).(context.Context); ok {
		return budget
	}
	return ctx
}

func (e *Engine) missingMemberInterface(ctx context.Context, ev enforce.ServingEvidence) bool {
	r := ev.TCSummary.Rejected
	if e.serving || ev.Quarantined || r == nil || r.Error != "read_failed" ||
		len(r.Objects) != 0 || r.Interface != e.appliedModel.Datapath.MemberIngress {
		return false
	}
	reader, ok := e.plane.(interface {
		InterfaceExists(context.Context, string) (bool, error)
	})
	if !ok {
		return false
	}
	exists, err := reader.InterfaceExists(ctx, r.Interface)
	return err == nil && ctx.Err() == nil && !exists
}

package e2e

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
)

// publisherTrace32 checks the live proof without requiring optional error
// details. Under D-154 (#443), the API parses the TEST ONLY If-Match: "0"
// like any version and compares it. No node row has version 0, so the forced
// write gets the ordinary 412 RESOURCE_VERSION_CONFLICT with
// details.current_resource_version. The retained forced proof from run 95fb7eab
// predates #443 and has empty details; replay tests still read that proof.
// Accept both shapes, recording current_resource_version whenever supplied.
func publisherTrace32(trace nodeWriteTrace, forced bool) (conflicts int, valid bool) {
	if len(trace.Attempts) == 0 {
		return 0, false
	}
	first := trace.Attempts[0]
	valid = trace.Status == StatusPass && trace.Outcome == "accepted" && first.IdempotencyKey != "" && len(first.BodySHA256) == 64
	for i, a := range trace.Attempts {
		valid = valid && !a.Transport && a.IdempotencyKey == first.IdempotencyKey && a.BodySHA256 == first.BodySHA256
		if a.Status == 412 && a.ErrorCode == "RESOURCE_VERSION_CONFLICT" {
			conflicts++
			read := a.Reread
			valid = valid && read != nil && read.Method == "GET" && read.Status == 200 && !read.Transport && read.ErrorCode == ""
			valid = valid && (a.CurrentVersion == "" || decimalVersion(a.CurrentVersion))
			if i+1 < len(trace.Attempts) {
				valid = valid && read != nil && trace.Attempts[i+1].IfMatch == read.ETag
			}
		} else {
			valid = valid && i == len(trace.Attempts)-1 && a.Status == 202 && a.Reread == nil
		}
	}
	valid = valid && trace.Attempts[len(trace.Attempts)-1].Status == 202
	if forced {
		valid = valid && len(trace.Attempts) == 2 && conflicts == 1 && first.IfMatch == `"0"`
	}
	return conflicts, valid
}

func TestAPI01_PublisherProofOptionalConflictVersion(t *testing.T) {
	for _, details := range []string{`{}`, `{"current_resource_version":"6"}`} {
		t.Run(details, func(t *testing.T) {
			var mu sync.Mutex
			var requests []string
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				mu.Lock()
				defer mu.Unlock()
				requests = append(requests, r.Method)
				switch len(requests) {
				case 1:
					w.WriteHeader(412)
					_, _ = fmt.Fprintf(w, `{"error":{"code":"RESOURCE_VERSION_CONFLICT","details":%s}}`, details)
				case 2:
					w.Header().Set("ETag", `"6"`)
					_, _ = io.WriteString(w, `{}`)
				case 3:
					w.WriteHeader(202)
				default:
					t.Error("unexpected extra request")
					w.WriteHeader(500)
				}
			}))
			defer server.Close()
			var trace nodeWriteTrace
			body := map[string]string{"name": "TEST ONLY"}
			out := (&httpSession{http: server.Client()}).writeNode(t.Context(), "PATCH", server.URL+"/node", server.URL+"/node", body, `"0"`, nodeFieldsMatch(body), []int{202}, func(_, raw string) {
				if err := json.Unmarshal([]byte(raw), &trace); err != nil {
					t.Fatal(err)
				}
			})
			mu.Lock()
			defer mu.Unlock()
			conflicts, valid := publisherTrace32(trace, true)
			if !out.accepted(202) || !valid || conflicts != 1 || fmt.Sprint(requests) != "[PATCH GET PATCH]" || trace.Attempts[1].IfMatch != `"6"` {
				t.Fatalf("proof rejected successful conflict recovery: %+v", trace)
			}
			wantVersion := "6"
			if details == `{}` {
				wantVersion = ""
			}
			if trace.Attempts[0].CurrentVersion != wantVersion {
				t.Fatal("current version was invented or lost")
			}
			trace.Attempts[1].IfMatch = `"5"`
			if _, valid := publisherTrace32(trace, true); valid {
				t.Fatal("proof accepted retry without the re-read ETag")
			}
		})
	}
}

